import{z as h,x as A,o as r,c as s,q as E,j as t,D as e,d as i,s as o,S as n,b as l}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"clip 与 clip-higher","description":"","frontmatter":{"title":"clip 与 clip-higher","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ppo-clip-higher.md","filePath":"llm/ppo-clip-higher.md","lastUpdated":1791063341000}'),B={name:"llm/ppo-clip-higher.md"};function m(d,a,c,_,g,D){const p=A("Mermaid");return r(),s("div",null,[a[2]||(a[2]=E('<h1 id="clip-与-clip-higher" tabindex="-1">clip 与 clip-higher <a class="header-anchor" href="#clip-与-clip-higher" aria-label="Permalink to &quot;clip 与 clip-higher&quot;">​</a></h1><div class="epigraph"><p>对称 ε 把低概率探索词的涨幅卡死；把上截单独抬高，熵才有地方回来。</p><footer>—— Schulman 等 PPO 的近端裁剪；Yu 等 DAPO 把上下 ε 拆开</footer></div><p><a href="/llm/gae-lambda">上一课</a>给出 \\(\\hat A_t\\)。PPO 用比率 \\(r_t(\\theta)=\\pi_\\theta/\\pi_{\\mathrm{old}}\\) 乘优势，再裁剪。缺口是：<strong>对称 \\(\\varepsilon\\) 对「抬低概率 token」过紧、对「压高概率 token」相对松，长链上熵塌。</strong> 本课写 clip 的不对称，不重导 clip 公式——公式见 <a href="/llm/ppo-llm">PPO</a>。DAPO 的 Clip-Higher 是本课的主工程结论。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>裁剪的非对称作用上一课单元已经用过：正优势时阻止 \\(r_t\\) 过大，负优势时阻止 \\(r_t\\) 过小。\\(\\varepsilon=0.2\\) 时，概率 \\(0.01\\) 的词最多升到约 \\(0.012\\)，而本来就很大的词几乎不受上界限制。推理 RL 需要把罕见但高优势的分叉词（「等等」「换一种证法」）抬起来；上截过紧，探索死，组内回复互为复制。<a href="/llm/grpo">GRPO</a> 沿用同一 clip，问题一样。</p><p>Yu 等人把上截改成 \\(1+\\varepsilon_{\\mathrm{high}}\\)、下截保持 \\(1-\\varepsilon_{\\mathrm{low}}\\)，\\(\\varepsilon_{\\mathrm{low}}=0.2\\)、\\(\\varepsilon_{\\mathrm{high}}=0.28\\)。再放大下截会把 token 概率压穿，采样空间崩。只改上截是为了放行正优势的探索词。</p><p><span class="marginnote">常见误区：初学者容易以为被 clip 的样本会被「拉回」区间。实际上越界一侧的梯度被置零——该 token 这一步就是不更新。clip 是刹车，不是弹簧。</span></p><h3 id="不要把-0-28-当成新物理常数" tabindex="-1">不要把 0.28 当成新物理常数 <a class="header-anchor" href="#不要把-0-28-当成新物理常数" aria-label="Permalink to &quot;不要把 0.28 当成新物理常数&quot;">​</a></h3><p>DAPO 的数是在 Qwen2.5-32B + 数学规则奖励上扫出来的。换模型、换长度、换 <a href="/llm/gspo">GSPO</a> 的序列比率，量纲都变。本课要的是「上下截分开扫」，不是抄 0.28。</p><p><span class="marginnote">梯度裁剪（grad clip）与比率 clip 不是一件事。前者管更新范数，后者管信任域。两件都要。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>目标仍是 PPO / GRPO 的 \\(\\min(r_t\\hat A, \\mathrm{clip}(r_t,1-\\varepsilon_{\\mathrm{low}},1+\\varepsilon_{\\mathrm{high}})\\hat A)\\)，只是两个 \\(\\varepsilon\\) 独立。监控：被上截命中的正优势 token 比例、熵、组内独特率。上截命中接近 0，说明 \\(\\varepsilon_{\\mathrm{high}}\\) 太松或没有探索；命中接近 1，说明步长相对 \\(\\varepsilon\\) 过大。DAPO 消融：朴素 GRPO 之后加上 Clip-Higher，AIME 从过滤后的 36 到 38，幅度小于动态采样，但对熵曲线关键。</p>',12)),(r(),t(n,null,{default:e(()=>[o(p,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20RT%5B%22%E6%AF%94%E7%8E%87%20r_t%22%5D%20--%3E%20LO%5B%22%E4%B8%8B%E6%88%AA%201%E2%88%92%CE%B5_low%20%E4%BF%9D%E8%B4%9F%E4%BC%98%E5%8A%BF%22%5D%0A%20%20RT%20--%3E%20HI%5B%22%E4%B8%8A%E6%88%AA%201%2B%CE%B5_high%20%E6%94%BE%E8%A1%8C%E6%8E%A2%E7%B4%A2%E8%AF%8D%22%5D%0A%20%20LO%20--%3E%20OBJ%5B%22%E8%A3%81%E5%89%AA%E4%BB%A3%E7%90%86%E7%9B%AE%E6%A0%87%22%5D%0A%20%20HI%20--%3E%20OBJ%0A%20%20OBJ%20--%3E%20ENT%5B%22%E7%86%B5%E6%98%AF%E5%90%A6%E5%9B%9E%E5%8D%87%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("p",null,"MiniMax-M1 后来认为大量 off-policy 轮次里 Clip-Higher 仍会丢掉分叉词，改 clip 重要性采样权重。那是后课截断 IS 的接口。本课范围：on-policy 近端目标里的不对称 \\(\\varepsilon\\)。",-1)),a[4]||(a[4]=l("h2",{id:"机制",tabindex:"-1"},[i("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=l("p",null,[i("正优势 + 低 \\(\\pi_{\\mathrm{old}}\\) 的 token，是「值得变常见的罕见动作」。对称上截把这条通道几乎关掉，策略只能微调已经常见的词，熵下降。抬上截等于扩大正向信任域、保持负向信任域，避免一边放探索一边把旧高概率词删光。熵回升后，"),l("a",{href:"/llm/grpo"},"GRPO"),i(" 的组内方差才回来，相对优势才有信号——与动态采样互补。")],-1)),a[6]||(a[6]=l("p",null,[l("span",{class:"marginnote"},"直觉类比：把上下截想成遛狗的两根伸缩绳——正向优势那根绳（往前探索）原本和负向那根一样长，狗刚迈步就被拽回；Clip-Higher 只把往前那根放长一点，往回拽的照旧。")],-1)),(r(),t(n,null,{default:e(()=>[o(p,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%BD%95%E8%A7%81%E6%8E%A2%E7%B4%A2%E8%AF%8D%EF%BC%9Ap%20%3D%200.01%22%5D%20--%3E%7C%22%E5%AF%B9%E7%A7%B0%E4%B8%8A%E6%88%AA%20%C3%971.2%22%7C%20B%5B%22%E6%9C%80%E5%A4%9A%200.012%EF%BC%8C%E7%BB%9D%E5%AF%B9%E5%A2%9E%E9%87%8F%200.002%22%5D%0A%20%20C%5B%22%E5%B8%B8%E8%A7%81%E8%AF%8D%EF%BC%9Ap%20%3D%200.50%22%5D%20--%3E%7C%22%E5%90%8C%E4%B8%80%E4%B8%8A%E6%88%AA%20%C3%971.2%22%7C%20D%5B%22%E6%9C%80%E5%A4%9A%200.60%EF%BC%8C%E7%BB%9D%E5%AF%B9%E5%A2%9E%E9%87%8F%200.10%22%5D%0A%20%20B%20--%3E%20E%5B%22%E6%8E%A2%E7%B4%A2%E9%80%9A%E9%81%93%E8%BF%91%E4%B9%8E%E5%85%B3%E9%97%AD%EF%BC%8C%E7%86%B5%E5%A1%8C%22%5D%0A%20%20D%20--%3E%20F%5B%22%E5%B8%B8%E8%A7%81%E8%AF%8D%E5%87%A0%E4%B9%8E%E4%B8%8D%E5%8F%97%E4%B8%8A%E7%95%8C%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20E%20--%3E%20G%5B%22%E5%8F%AA%E6%94%BE%E5%AE%BD%E4%B8%8A%E6%88%AA%EF%BC%9A1%20%2B%20%CE%B5_high%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=E('<p>这张图回答「为什么对称 ε 卡死探索」：同样的相对上界，绝对概率质量全在常见词那边。</p><p><span class="marginnote">\\(\\varepsilon_{\\mathrm{high}}-\\varepsilon_{\\mathrm{low}}\\) 不是学习率。学习率过大时，未裁剪侧一步就冲出区间，clip 只是更频繁地截断，有效更新变稀。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>偏好 RM 上优势噪声大，抬上截可能放大 RM 抖动，过优化更快。可验证 0/1 是 Clip-Higher 的主场。<a href="/llm/kl-free-rl">无 KL 的 RL</a> 更依赖这条探索通道，因为没有参考分布把策略拉回。价值函数与 GAE 不因 clip 改变定义。下一课才谈 critic 从哪初始化。序列级比率（GSPO）的 \\(\\varepsilon\\) 量纲不同，禁止把 0.28 抄过去。</p><p><span class="marginnote">为什么重要：要盯「上截命中率」——长期为 \\(0\\) 说明 \\(\\varepsilon_{\\mathrm{high}}\\) 放了白放；逼近 \\(1\\) 说明步长太大在硬撞墙。它必须和熵曲线画在同一张图上看，单独一个数没有结论。</span></p><p>上截与下截要分开记进配置，并与熵曲线同图；只改一个 ε 达不到 DAPO 消融里的那一截增益。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对称 ε 卡死低概率词的正向涨幅，长链熵塌。</li><li>Clip-Higher 拆开上下截：上截松、下截紧，放行探索、防止压穿。</li><li>具体数字要扫；序列级比率不要抄 token 级 ε。</li><li>与动态采样、熵监控一起看，不要单改一个 ε。</li><li>出处：Schulman 等 PPO, 2017；Yu 等 DAPO；对照 MiniMax-M1 / GSPO 的后续改法。</li></ul>',8))])}const f=h(B,[["render",m]]);export{P as __pageData,f as default};
